def is_polite(n):
    def is_polite_helper(n, i):
        if n == 1:
            return True
        if n % i == 0:
            return False
        return is_polite_helper(n, i + 1)

    for i in range(2, int(n ** 0.5) + 1):
        if is_polite_helper(n, i):
            return False
    return True

def nth_polite_number(n):
